INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('topic:TOPIC31-001','topic','','Diagnostyka sekcji zasilania CPU (VRM)','CPU VRM power-stage diagnostics','description: Analiza wejścia EPS, kontrolera PWM, faz zasilania, MOSFET-ów i cewek na podstawie schematu konkretnej płyty. symptoms: PC wyłącza się pod obciążeniem, CPU nie osiąga deklarowanych zegarów lub płyta nie przechodzi POST. diagnosis: Oddziel brak sygnału EN/PWRGOOD, ograniczenie termiczne, przeciążenie i problem firmware. Odczytaj logi i porównaj zachowanie na ustawieniach domyślnych. repair: Naprawa ma wynikać z pomiarów kontrolera, przebiegu zasilania i oględzin elementów; wymieniaj tylko potwierdzony uszkodzony element. warning: Nie wykonuj pomiarów po stronie sieciowej PSU. Pomiary na pracującej płycie wymagają kwalifikacji, sond zabezpieczonych i dokumentacji. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. symptomsEn: Symptoms and scope: Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. repairEn: Repair only after evidence confirms the cause. Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-002','topic','','Diagnostyka braku obrazu z dedykowanej karty GPU','Dedicated GPU no-display diagnostics','description: Oddziel usterkę karty, slotu PCIe, przewodu obrazu, monitora, firmware i sterownika. symptoms: Wentylatory ruszają, ale monitor nie wykrywa sygnału; system może uruchamiać się w tle. diagnosis: Sprawdź POST/debug LED, wyjście płyty, inny przewód i ekran oraz wykrycie urządzenia w systemie. repair: Dopiero po izolacji przyczyny wykonaj kontrolę złącza, zasilania PCIe i test karty w zgodnym, sprawnym zestawie. warning: Nie wkładaj i nie wyjmuj GPU przy zasilonym komputerze; nie dotykaj styków ani nie zwieraj pinów slotu. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. symptomsEn: Symptoms and scope: Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. repairEn: Repair only after evidence confirms the cause. Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-003','topic','','Artefakty obrazu i niestabilność pamięci VRAM','Display artifacts and VRAM instability','description: Rozpoznawanie artefaktów zależnych od temperatury, obciążenia, sterownika i połączenia wyświetlacza. symptoms: Kolorowe bloki, migotanie, błędy tekstur, reset sterownika lub czarny ekran. diagnosis: Zapisz, czy artefakt występuje w BIOS, na pulpicie, w zrzucie ekranu i na innym monitorze. Porównaj temperatury oraz logi. repair: Przyczynę potwierdź powtarzalnym testem; sterownik, przewód lub monitor wyklucz przed podejrzeniem VRAM. warning: Nie używaj długich testów obciążeniowych przy artefaktach, przegrzewaniu lub zapachu spalenizny. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Identify artifacts correlated with temperature, load, driver and display connection. symptomsEn: Symptoms and scope: Identify artifacts correlated with temperature, load, driver and display connection. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Identify artifacts correlated with temperature, load, driver and display connection. repairEn: Repair only after evidence confirms the cause. Identify artifacts correlated with temperature, load, driver and display connection. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Identify artifacts correlated with temperature, load, driver and display connection.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-004','topic','','Odtwarzanie BIOS z funkcji Flashback','BIOS recovery using Flashback','description: Przygotowanie zgodnego obrazu firmware, nośnika USB, nazwy pliku i sekwencji odzyskiwania według OEM. symptoms: Płyta nie przechodzi POST po przerwanym update albo firmware nie uruchamia konfiguracji. diagnosis: Ustal dokładny model i rewizję PCB; potwierdź, że dana płyta ma funkcję Flashback i sprawdź jej instrukcję. repair: Użyj wyłącznie obrazu z oficjalnej strony dla dokładnej rewizji. Zachowaj stabilne zasilanie i nie przerywaj procesu. warning: Nie flashuj obrazu z podobnego modelu. Nie odłączaj zasilania, gdy dioda wskazuje trwający zapis. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. symptomsEn: Symptoms and scope: Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. repairEn: Repair only after evidence confirms the cause. Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-005','topic','','Analiza ustawień UEFI i kolejności bootowania','UEFI settings and boot-order analysis','description: Rozróżnianie UEFI/Legacy, GPT/MBR, Secure Boot, CSM, trybu kontrolera i wpisów boot managera. symptoms: Komunikat no bootable device, zniknięcie wpisu Windows Boot Manager lub pętla firmware. diagnosis: Zapisz ustawienia przed zmianą; sprawdź wykrywanie dysku i stan partycji bez modyfikowania danych. repair: Przywracaj ustawienia pojedynczo i zgodnie z pierwotnym sposobem instalacji systemu. warning: Nie przełączaj AHCI/RAID/VMD ani Secure Boot bez oceny wpływu na rozruch i klucze odzyskiwania. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. symptomsEn: Symptoms and scope: Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. repairEn: Repair only after evidence confirms the cause. Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-006','topic','','Diagnostyka TPM 2.0 i Secure Boot','TPM 2.0 and Secure Boot diagnostics','description: Weryfikacja stanu TPM, trybu Secure Boot, kluczy platformy i wymagań systemu. symptoms: Windows zgłasza brak TPM, stan Secure Boot jest niepoprawny albo aplikacja nie spełnia wymagań. diagnosis: Sprawdź `tpm.msc`, msinfo32 i dokumentację UEFI; rozróżnij TPM firmware, dTPM i ustawienia platformy. repair: Ustawienia zmieniaj po kopii kluczy odzyskiwania BitLocker i sprawdzeniu wymagań producenta. warning: Nie czyść TPM na urządzeniu użytkownika bez kopii kluczy i zgody — może to uniemożliwić dostęp do danych. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. symptomsEn: Symptoms and scope: Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. repairEn: Repair only after evidence confirms the cause. Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Verify TPM state, Secure Boot mode, platform keys and operating-system requirements.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-007','topic','','Diagnostyka kontrolera EC/KBC','Embedded Controller (EC/KBC) diagnostics','description: Rozpoznawanie objawów związanych z kontrolerem klawiatury, przyciskiem Power, ładowaniem i sekwencją startową. symptoms: Brak reakcji przycisku, nietypowe diody, brak ładowania lub nieregularny start. diagnosis: Sprawdź złącza, przycisk, baterię, adapter i kody POST; odczyty linii EC wykonuj tylko według schematu. repair: Weryfikuj firmware EC i procedurę producenta; programowanie układu powierz technikowi z właściwym sprzętem. warning: Nie zwieraj pinów EC ani nie wgrywaj wsadu z innej rewizji płyty. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. symptomsEn: Symptoms and scope: Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. repairEn: Repair only after evidence confirms the cause. Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Recognise symptoms involving keyboard controller, power button, charging and startup sequencing.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-008','topic','','Ocena kondycji baterii laptopa','Laptop battery health assessment','description: Analiza pojemności projektowej i pełnego ładowania, cykli, napięcia, temperatury i komunikacji BMS. symptoms: Krótki czas pracy, nagłe wyłączenie, brak ładowania lub komunikat o niewykrytej baterii. diagnosis: Porównaj raport systemu z diagnostyką OEM, sprawdź zasilacz i zachowanie na zasilaniu sieciowym. repair: Wymieniaj baterię tylko na zgodny, certyfikowany moduł; po wymianie wykonaj kalibrację, jeśli zaleca ją producent. warning: Spuchniętej, przebitej lub przegrzewającej się baterii nie naciskaj, nie przebijaj ani nie ładuj. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. symptomsEn: Symptoms and scope: Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. repairEn: Repair only after evidence confirms the cause. Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Analyse design/full-charge capacity, cycles, voltage, temperature and BMS communication.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-009','topic','','Analiza negocjacji USB-C Power Delivery','USB-C Power Delivery negotiation analysis','description: Rozpoznawanie ról źródła i odbiornika, komunikatów CC, profili PDO i ograniczeń kabla/adaptera. symptoms: Urządzenie ładuje się wolno, przerywa ładowanie lub działa tylko z wybranym adapterem. diagnosis: Porównaj adapter, kabel e-marked, port i odbiornik; użyj miernika PD zgodnego ze specyfikacją. repair: Wymień wyłącznie element potwierdzony testem; port i kontroler analizuj na schemacie dokładnej rewizji. warning: Nie podawaj napięcia na nieznane piny ani nie używaj przypadkowych adapterów laboratoryjnych. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. symptomsEn: Symptoms and scope: Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. repairEn: Repair only after evidence confirms the cause. Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Identify source/sink roles, CC communication, PDO profiles and cable/adapter limitations.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-010','topic','','Diagnostyka Thunderbolt i stacji dokującej','Thunderbolt and docking-station diagnostics','description: Izolowanie problemów firmware, kabla, portu, autoryzacji, zasilania i zgodności urządzenia. symptoms: Dock nie wykrywa monitorów, LAN, USB lub ładowania mimo podłączenia. diagnosis: Sprawdź certyfikację i oznaczenia kabla, firmware docka, listę zgodności oraz zdarzenia systemowe. repair: Testuj osobno monitor, zasilanie, USB i LAN; aktualizuj firmware wyłącznie według OEM. warning: Nie wymuszaj niezgodnego trybu zasilania; aktualizacja docka może przerwać pracę wszystkich portów. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Isolate firmware, cable, port, authorization, power and device-compatibility issues. symptomsEn: Symptoms and scope: Isolate firmware, cable, port, authorization, power and device-compatibility issues. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Isolate firmware, cable, port, authorization, power and device-compatibility issues. repairEn: Repair only after evidence confirms the cause. Isolate firmware, cable, port, authorization, power and device-compatibility issues. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Isolate firmware, cable, port, authorization, power and device-compatibility issues.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-011','topic','','Testowanie portów USB4 i trybów Alt Mode','USB4 ports and Alt Mode testing','description: Weryfikacja możliwości portu: dane, wideo, zasilanie, szybkość i zgodność z urządzeniami. symptoms: Port rozpoznaje dysk, ale nie monitor; przepustowość spada albo dock działa częściowo. diagnosis: Odczytaj specyfikację modelu, topologię kontrolera i możliwości przewodu; porównaj kilka znanych urządzeń. repair: Zaktualizuj sterowniki chipsetu i firmware OEM; naprawę sprzętową oprzyj o inspekcję i schemat. warning: Nie zakładaj, że każde gniazdo USB-C obsługuje Thunderbolt, USB4 lub DisplayPort. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Verify port capabilities: data, video, power, speed and device compatibility. symptomsEn: Symptoms and scope: Verify port capabilities: data, video, power, speed and device compatibility. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Verify port capabilities: data, video, power, speed and device compatibility. repairEn: Repair only after evidence confirms the cause. Verify port capabilities: data, video, power, speed and device compatibility. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Verify port capabilities: data, video, power, speed and device compatibility.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-012','topic','','Diagnostyka temperatur i throttlingu NVMe','NVMe temperature and thermal-throttling diagnostics','description: Analiza temperatury kontrolera i NAND, throttlingu, radiatora, termopadu oraz obciążenia I/O. symptoms: Transfer spada po chwili, dysk znika pod obciążeniem lub SMART zapisuje ostrzeżenia. diagnosis: Zapisz temperatury, throttling i log SMART; porównaj warunki przepływu powietrza i specyfikację dysku. repair: Dobierz radiator i termopad według wymiarów; nie zakrywaj elementów nieprzewidzianych przez projekt. warning: Przy podejrzeniu awarii nośnika ogranicz zapisy i najpierw zabezpiecz dane. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Analyse controller/NAND temperature, throttling, heatsink, thermal pad and I/O load. symptomsEn: Symptoms and scope: Analyse controller/NAND temperature, throttling, heatsink, thermal pad and I/O load. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Analyse controller/NAND temperature, throttling, heatsink, thermal pad and I/O load. repairEn: Repair only after evidence confirms the cause. Analyse controller/NAND temperature, throttling, heatsink, thermal pad and I/O load. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Analyse controller/NAND temperature, throttling, heatsink, thermal pad and I/O load.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-013','topic','','Analiza SMART dysków SATA i HDD','SATA and HDD SMART analysis','description: Interpretacja atrybutów, logów błędów, liczby realokacji i sektorów niestabilnych. symptoms: Zawieszanie systemu, długie odczyty, kliknięcia, błędy CRC lub znikanie dysku. diagnosis: Porównaj SMART z logiem producenta i kablem SATA; odróżnij błędy interfejsu od mediów. repair: Przy ważnych danych wykonaj najpierw obraz sektorowy; wymianę uzasadnij trendem i diagnostyką. warning: Nie uruchamiaj długich testów powierzchni przy klikającym lub degradującym się dysku z ważnymi danymi. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Interpret SMART attributes, error logs, reallocated and pending sectors. symptomsEn: Symptoms and scope: Interpret SMART attributes, error logs, reallocated and pending sectors. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Interpret SMART attributes, error logs, reallocated and pending sectors. repairEn: Repair only after evidence confirms the cause. Interpret SMART attributes, error logs, reallocated and pending sectors. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Interpret SMART attributes, error logs, reallocated and pending sectors.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-014','topic','','Plan bezpiecznego obrazowania nośnika','Safe storage imaging and recovery planning','description: Plan pracy z niestabilnym HDD/SSD: priorytety, obraz sektorowy, logi i kopia robocza. symptoms: Dysk ma błędy odczytu, utrata plików lub niestabilne połączenie. diagnosis: Oceń, czy nośnik jest mechanicznie stabilny; ustal priorytet danych i ogranicz niepotrzebne uruchomienia. repair: Obrazuj do nośnika o odpowiedniej pojemności; odzyskuj z kopii, nie z oryginału. warning: Przy stukaniu, zapachu spalenizny, zalaniu lub awarii głowic przerwij i rozważ laboratorium odzysku. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Plan work on unstable HDD/SSD: priorities, sector image, logs and working copy. symptomsEn: Symptoms and scope: Plan work on unstable HDD/SSD: priorities, sector image, logs and working copy. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Plan work on unstable HDD/SSD: priorities, sector image, logs and working copy. repairEn: Repair only after evidence confirms the cause. Plan work on unstable HDD/SSD: priorities, sector image, logs and working copy. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Plan work on unstable HDD/SSD: priorities, sector image, logs and working copy.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-015','topic','','Obsługa klucza odzyskiwania BitLocker','BitLocker recovery-key handling','description: Identyfikacja przyczyny recovery prompt po zmianie BIOS, TPM, płyty, Secure Boot lub boot managera. symptoms: System żąda 48-cyfrowego klucza po aktualizacji firmware lub zmianie konfiguracji. diagnosis: Nie resetuj TPM; ustal identyfikator klucza, właściciela urządzenia i wcześniejsze zmiany. repair: Odzyskaj klucz z autoryzowanego źródła użytkownika/organizacji; dopiero później przywracaj konfigurację. warning: Nie proś o przesłanie klucza do czatu ani raportu. Nigdy nie obchodź szyfrowania. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Identify why recovery appears after BIOS, TPM, board, Secure Boot or boot-manager changes. symptomsEn: Symptoms and scope: Identify why recovery appears after BIOS, TPM, board, Secure Boot or boot-manager changes. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Identify why recovery appears after BIOS, TPM, board, Secure Boot or boot-manager changes. repairEn: Repair only after evidence confirms the cause. Identify why recovery appears after BIOS, TPM, board, Secure Boot or boot-manager changes. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Identify why recovery appears after BIOS, TPM, board, Secure Boot or boot-manager changes.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-016','topic','','Naprawa środowiska odzyskiwania WinRE','Windows Recovery Environment (WinRE) repair','description: Analiza stanu WinRE, lokalizacji obrazu, partycji odzyskiwania i dostępnych opcji naprawy. symptoms: Zaawansowane uruchamianie nie otwiera się, reset zawodzi albo recovery image nie jest dostępny. diagnosis: Zapisz status `reagentc /info`, układ partycji i komunikaty; sprawdź szyfrowanie oraz kopię danych. repair: Użyj najmniej destrukcyjnej opcji i dokumentacji Microsoft; naprawę partycji wykonuj dopiero po kopii. warning: Nie kasuj partycji recovery ani nie wykonuj resetu przed zabezpieczeniem danych klienta. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Analyse WinRE state, image location, recovery partition and available repair options. symptomsEn: Symptoms and scope: Analyse WinRE state, image location, recovery partition and available repair options. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Analyse WinRE state, image location, recovery partition and available repair options. repairEn: Repair only after evidence confirms the cause. Analyse WinRE state, image location, recovery partition and available repair options. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Analyse WinRE state, image location, recovery partition and available repair options.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-017','topic','','Diagnostyka BCD i Windows Boot Manager','BCD and Windows Boot Manager diagnostics','description: Rozpoznawanie problemów wpisu boot, partycji EFI, kolejności rozruchu i plików systemowych. symptoms: INACCESSIBLE_BOOT_DEVICE, no bootable device, brak wpisu Windows Boot Manager. diagnosis: Ustal UEFI/GPT, wykrywanie dysku i stan partycji EFI; nie wykonuj zapisu przed rozpoznaniem dysku. repair: Odtwarzaj BCD tylko po potwierdzeniu układu partycji i wersji systemu. warning: Uważaj na BitLocker i wiele systemów na jednym dysku; nie formatuj EFI „na próbę”. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Identify boot-entry, EFI system partition, boot order and system-file problems. symptomsEn: Symptoms and scope: Identify boot-entry, EFI system partition, boot order and system-file problems. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Identify boot-entry, EFI system partition, boot order and system-file problems. repairEn: Repair only after evidence confirms the cause. Identify boot-entry, EFI system partition, boot order and system-file problems. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Identify boot-entry, EFI system partition, boot order and system-file problems.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-018','topic','','Diagnostyka konfliktu sterowników','Windows driver conflict diagnostics','description: Weryfikacja identyfikatora sprzętu, wersji, podpisu, źródła i historii sterownika. symptoms: Żółty wykrzyknik w Menedżerze urządzeń, kod 10/31/43, brak funkcji urządzenia. diagnosis: Zapisz hardware ID i kod błędu; sprawdź sterownik OEM oraz zdarzenia przed i po zmianie. repair: Użyj pakietu zgodnego z modelem; najpierw utwórz punkt przywracania i zachowaj instalator. warning: Nie instaluj automatycznych paczek z przypadkowych serwisów i nie wyłączaj podpisu sterowników na stałe. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Verify hardware ID, version, signature, source and driver history. symptomsEn: Symptoms and scope: Verify hardware ID, version, signature, source and driver history. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Verify hardware ID, version, signature, source and driver history. repairEn: Repair only after evidence confirms the cause. Verify hardware ID, version, signature, source and driver history. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Verify hardware ID, version, signature, source and driver history.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-019','topic','','Analiza minidump i BSOD','Minidump and BSOD analysis','description: Korelacja bugcheck, modułu, czasu, sterownika i historii zmian; rozróżnianie objawu od winowajcy. symptoms: Powtarzający się BSOD, restart bez komunikatu lub awaria pod określonym obciążeniem. diagnosis: Zabezpiecz pliki dump, odczytaj kod i stack w WinDbg; porównaj kilka zdarzeń, nie tylko jeden moduł. repair: Aktualizuj/wycofuj sterownik tylko po potwierdzeniu korelacji i testach. warning: Nie publikuj plików dump bez usunięcia danych osobowych, ścieżek, nazw i tokenów. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Correlate bugcheck, module, time, driver and change history; distinguish symptom from cause. symptomsEn: Symptoms and scope: Correlate bugcheck, module, time, driver and change history; distinguish symptom from cause. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Correlate bugcheck, module, time, driver and change history; distinguish symptom from cause. repairEn: Repair only after evidence confirms the cause. Correlate bugcheck, module, time, driver and change history; distinguish symptom from cause. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Correlate bugcheck, module, time, driver and change history; distinguish symptom from cause.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-020','topic','','Diagnostyka błędów WHEA i PCIe','WHEA and PCIe error diagnostics','description: Interpretacja WHEA Logger, AER, link retraining i błędów urządzeń PCIe. symptoms: Losowe restarty, WHEA_UNCORRECTABLE_ERROR, logi corrected hardware error. diagnosis: Zapisz source, bank, APIC ID, PCIe BDF i czas; porównaj z temperaturą, BIOS i konfiguracją. repair: Przetestuj ustawienia domyślne, urządzenia i sloty pojedynczo; aktualizuj firmware po weryfikacji. warning: Nie podnoś napięć ani nie zmieniaj PCIe link speed bez planu i świadomości ryzyka. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Interpret WHEA Logger, AER, link retraining and PCIe device errors. symptomsEn: Symptoms and scope: Interpret WHEA Logger, AER, link retraining and PCIe device errors. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Interpret WHEA Logger, AER, link retraining and PCIe device errors. repairEn: Repair only after evidence confirms the cause. Interpret WHEA Logger, AER, link retraining and PCIe device errors. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Interpret WHEA Logger, AER, link retraining and PCIe device errors.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-021','topic','','Czytanie Podglądu zdarzeń i Reliability Monitor','Event Viewer and Reliability Monitor analysis','description: Filtrowanie zdarzeń systemowych, aplikacyjnych i sprzętowych w osi czasu. symptoms: Użytkownik zgłasza „sam się wyłącza”, „zawiesza” lub „wolno działa”. diagnosis: Skoreluj zdarzenia z godziną objawu, źródłem, identyfikatorem, kodem i aktualizacjami. repair: Zalecenia oprzyj o powtarzalny wzorzec, nie pojedynczy Kernel-Power 41. warning: Nie usuwaj logów przed eksportem i nie traktuj ostrzeżenia jako jednoznacznej awarii części. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Filter system, application and hardware events on a timeline. symptomsEn: Symptoms and scope: Filter system, application and hardware events on a timeline. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Filter system, application and hardware events on a timeline. repairEn: Repair only after evidence confirms the cause. Filter system, application and hardware events on a timeline. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Filter system, application and hardware events on a timeline.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-022','topic','','Naprawa obrazu Windows przy użyciu DISM i SFC','Repairing Windows image with DISM and SFC','description: Kolejność kontroli komponent store, źródła naprawy, integralności plików i logów. symptoms: Błędy aktualizacji, uszkodzone pliki systemu lub problemy z funkcjami Windows. diagnosis: Zapisz edition/build, status DISM, kod zakończenia i CBS.log; upewnij się, że źródło pasuje do wersji. repair: Wykonaj DISM i SFC zgodnie z dokumentacją Microsoft; sprawdź ponownie po restarcie. warning: Nie używaj losowego ISO o innej kompilacji jako źródła; wykonaj kopię danych. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Sequence component-store, repair-source, system-file and log checks. symptomsEn: Symptoms and scope: Sequence component-store, repair-source, system-file and log checks. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Sequence component-store, repair-source, system-file and log checks. repairEn: Repair only after evidence confirms the cause. Sequence component-store, repair-source, system-file and log checks. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Sequence component-store, repair-source, system-file and log checks.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-023','topic','','Test stabilności RAM DDR5 i profili XMP/EXPO','DDR5 RAM and XMP/EXPO stability testing','description: Rozdzielenie problemu modułu, slotu, kontrolera, treningu pamięci i profilu OC. symptoms: Błędy MemTest, restarty, długie treningi pamięci lub niestabilność po aktywacji profilu. diagnosis: Testuj ustawienia JEDEC, pojedynczy moduł, sloty według manuala i wersję BIOS. repair: Najpierw potwierdź stabilność bez profilu; ustawienia XMP/EXPO są profilem OC, nie gwarancją. warning: Nie mieszaj zestawów o różnych parametrach; nie zwiększaj napięć bez dokumentacji i kompetencji. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Separate DIMM, slot, controller, memory training and overclock-profile issues. symptomsEn: Symptoms and scope: Separate DIMM, slot, controller, memory training and overclock-profile issues. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Separate DIMM, slot, controller, memory training and overclock-profile issues. repairEn: Repair only after evidence confirms the cause. Separate DIMM, slot, controller, memory training and overclock-profile issues. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Separate DIMM, slot, controller, memory training and overclock-profile issues.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-024','topic','','Rozróżnianie błędu DIMM i slotu pamięci','Distinguishing DIMM and memory-slot faults','description: Krzyżowe testy modułów i slotów z zapisem konfiguracji oraz kodów POST. symptoms: Komputer startuje tylko z jednym modułem albo zgłasza błąd pamięci. diagnosis: Oznacz moduły A/B i sloty; sprawdź listę QVL, osadzenie oraz sygnały POST. repair: Wymień moduł lub skieruj płytę do dalszej diagnozy dopiero po odtworzeniu błędu. warning: Odłącz źródła zasilania przed demontażem; nie dotykaj styków palcami. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Cross-test DIMMs and slots while recording configuration and POST codes. symptomsEn: Symptoms and scope: Cross-test DIMMs and slots while recording configuration and POST codes. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Cross-test DIMMs and slots while recording configuration and POST codes. repairEn: Repair only after evidence confirms the cause. Cross-test DIMMs and slots while recording configuration and POST codes. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Cross-test DIMMs and slots while recording configuration and POST codes.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC31-025','topic','','Diagnostyka kontrolera pamięci CPU','CPU integrated memory controller diagnostics','description: Analiza błędów zależnych od kanału, obciążenia, socketu, montażu CPU i firmware. symptoms: Błędy pojawiają się na konkretnym kanale lub przy obsadzeniu dwóch modułów. diagnosis: Porównaj QVL, sloty zalecane przez producenta i konfigurację minimalną; sprawdź socket pod powiększeniem. repair: Weryfikuj płytę i CPU na znanej konfiguracji; naprawę socketu powierz wyspecjalizowanemu serwisowi. warning: Nie dociskaj modułów i nie prostuj pinów socketu bez odpowiedniej optyki i kwalifikacji. source: Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0','descriptionEn: Analyse channel-dependent errors, loading, socket, CPU mounting and firmware. symptomsEn: Symptoms and scope: Analyse channel-dependent errors, loading, socket, CPU mounting and firmware. Record the condition and exact system context. diagnosisEn: Diagnostic approach: confirm the model/revision, isolate one hypothesis at a time, review logs and compare measurements to OEM references. Topic scope: Analyse channel-dependent errors, loading, socket, CPU mounting and firmware. repairEn: Repair only after evidence confirms the cause. Analyse channel-dependent errors, loading, socket, CPU mounting and firmware. Follow model-specific service instructions and perform a repeatable acceptance test. warningEn: Stop when there is smoke, liquid, a swollen battery, exposed mains voltage or an unknown short. Never guess the pinout or firmware. Analyse channel-dependent errors, loading, socket, CPU mounting and firmware.','','Akademia Serwisu PRO — opracowanie szkoleniowe 3.1.0'),
('topic:TOPIC311-001','topic','','Rozpoznawanie sekwencji zasilania płyty laptopa','Laptop motherboard power-sequence analysis','description: Prześledź tor od DC-IN/USB-C przez ładowarkę, zabezpieczenia, linie always-on, sygnały enable i power-good, aż po stany S0. Wartości i nazwy sygnałów zależą od konkretnej płyty. symptoms: Laptop nie reaguje, pobór prądu zatrzymuje się na jednym etapie albo urządzenie włącza się i natychmiast wyłącza. diagnosis: Porównaj zachowanie przy znanym sprawnym zasilaczu, obserwuj prąd wejściowy i sprawdź dokumentację. Nie zakładaj, że sekwencja jest identyczna między platformami. repair: Nie podawaj napięć ani kolejności sygnałów z innej płyty. Pracuj tylko z udokumentowanymi punktami pomiarowymi; nie mierz strony sieciowej zasilacza. warning: Ustal model i rewizję; odłącz zasilanie i postępuj według procedury baterii.','descriptionEn: Trace the path from DC input or USB-C through charging, protection, always-on rails, enable and power-good signals, and finally the S0 state. Signal names and voltage limits are board-specific. symptomsEn: The laptop is unresponsive, current draw stops at one stage, or the device powers on and immediately shuts down. diagnosisEn: Compare behaviour with a known-good compatible adapter, observe input current and consult the exact board documentation. Do not assume identical sequences across platforms. repairEn: Never transfer voltage values or signal order from another board. Use documented test points only; never probe the mains side of a power supply. warningEn: Confirm the model and revision; disconnect power and follow the battery isolation procedure.','',''),
('topic:TOPIC311-002','topic','','Analiza układu ładowania i kontrolera baterii','Battery charger and fuel-gauge controller analysis','description: Oddziel problem adaptera, portu, toru wejściowego, kontrolera ładowania, pakietu, BMS i komunikacji SMBus. Kondycja ogniw nie jest tym samym co zdolność ładowania. symptoms: Bateria nie ładuje się, poziom skacze, system zgłasza nieznany akumulator albo laptop działa wyłącznie z adaptera. diagnosis: Sprawdź moc adaptera, komunikaty systemu i dane baterii. Porównaj z dokumentacją OEM i nie wymuszaj ładowania pakietu z nieznanym stanem. repair: Spuchnięta, gorąca, przebita lub pachnąca bateria oznacza natychmiastowe przerwanie pracy i bezpieczną procedurę postępowania z baterią. warning: Zapisz model baterii i identyfikator części bez ujawniania danych klienta.','descriptionEn: Separate adapter, port, input path, charger controller, battery pack, BMS and SMBus communication faults. Cell health is not the same as charging functionality. symptomsEn: The battery does not charge, the reported percentage jumps, the system reports an unknown battery, or the laptop runs only on the adapter. diagnosisEn: Check adapter wattage, system messages and battery telemetry. Compare them with OEM documentation and never force-charge a pack of unknown condition. repairEn: A swollen, hot, punctured or odorous battery requires immediate work stoppage and the approved battery safety procedure. warningEn: Record the battery model and part identifier without exposing customer data.','',''),
('topic:TOPIC311-003','topic','','Diagnostyka sygnału PWRBTN, LID i czujników laptopa','Laptop PWRBTN, lid-switch and sensor diagnostics','description: Przyczyną może być przycisk, taśma, czujnik Halla, magnes, ustawienia ACPI, firmware EC lub sterownik. Objaw zależy od konstrukcji modelu. symptoms: Laptop nie włącza się przyciskiem, nie wybudza po otwarciu klapy lub samoczynnie usypia. diagnosis: Porównaj zachowanie z ustawieniami systemu i danymi diagnostycznymi producenta. Nie zwieraj pinów na chybił trafił. repair: Nie wykonuj prób zwarciowych nieopisanych styków. Przed demontażem odłącz baterię zgodnie z instrukcją. warning: Zapisz, czy problem występuje na zasilaczu, baterii i po wznowieniu.','descriptionEn: Possible causes include the button, cable, Hall sensor, magnet, ACPI settings, EC firmware or driver. Behaviour depends on the model design. symptomsEn: The laptop does not respond to the power button, fails to wake when the lid opens, or enters sleep unexpectedly. diagnosisEn: Compare behaviour with OS settings and OEM diagnostics. Never short unidentified pins. repairEn: Do not short unidentified contacts. Disconnect the battery according to the service manual before disassembly. warningEn: Record whether the issue occurs on AC, battery and after resume.','',''),
('topic:TOPIC311-004','topic','','Diagnostyka toru audio HDMI, DisplayPort i USB','HDMI, DisplayPort and USB audio path diagnostics','description: Oddziel urządzenie wyjściowe, profil systemu, sterownik GPU/audio, EDID, kabel i firmware stacji. HDMI/DP może udostępniać osobne urządzenie audio. symptoms: Brak dźwięku z monitora, stacji dokującej lub interfejsu USB mimo prawidłowego obrazu. diagnosis: Sprawdź listę urządzeń wyjściowych, poziom głośności aplikacji i identyfikację monitora. Porównaj połączenie bez stacji. repair: Nie instaluj pakietów sterowników z nieoficjalnych serwisów. Używaj oprogramowania dla dokładnego modelu. warning: Zapisz typ połączenia, model monitora i urządzenia audio.','descriptionEn: Separate output device, OS profile, GPU/audio driver, EDID, cable and dock firmware. HDMI/DP can expose a separate audio endpoint. symptomsEn: No sound from a monitor, dock or USB interface although video works correctly. diagnosisEn: Check output devices, application volume and monitor identification. Compare a direct connection without the dock. repairEn: Do not install driver bundles from unofficial sites. Use software intended for the exact model. warningEn: Record connection type, monitor model and audio device.','',''),
('topic:TOPIC311-005','topic','','Diagnostyka magistrali PCI Express i urządzeń końcowych','PCI Express link and endpoint diagnostics','description: Sprawdź generację, szerokość łącza, topologię, bifurkację, slot, riser, ustawienia firmware oraz błędy korekcyjne. Negocjowana prędkość zależy od obu końców i jakości toru. symptoms: Urządzenie PCIe znika, działa z niższą szerokością łącza lub pojawiają się błędy WHEA. diagnosis: Porównaj urządzenie w innym wspieranym slocie i bez risera. Odczytaj logi i parametry łącza; nie wymuszaj nieobsługiwanej generacji. repair: Przed manipulacją kartą odłącz zasilanie i zabezpiecz ESD. Nie wkładaj ani nie wyjmuj urządzenia pod napięciem, chyba że platforma jawnie wspiera hot-plug. warning: Zapisz model płyty, procesora, karty i topologię slotów.','descriptionEn: Check generation, link width, topology, bifurcation, slot, riser, firmware settings and corrected errors. Negotiated speed depends on both endpoints and signal integrity. symptomsEn: A PCIe device disappears, negotiates a lower link width, or triggers WHEA errors. diagnosisEn: Test the device in another supported slot and without a riser. Review logs and link parameters; do not force an unsupported generation. repairEn: Disconnect power and use ESD precautions before handling a card. Do not hot-plug unless the platform explicitly supports it. warningEn: Record board, CPU, card models and slot topology.','',''),
('topic:TOPIC311-006','topic','','Ocena kondycji kondensatorów i śladów przegrzania','Capacitor condition and thermal-damage inspection','description: Oględziny mogą ujawnić pęknięcia, wybrzuszenie, wyciek, odbarwienia laminatu lub nadpalone złącza. Sam wygląd nie potwierdza wszystkich awarii kondensatorów. symptoms: Niestabilność, restart, brak startu albo widoczne przebarwienia i korozja na PCB. diagnosis: Udokumentuj miejsce i porównaj oznaczenia z dokumentacją. Pomiary pojemności/ESR wykonuj po bezpiecznym odłączeniu i rozładowaniu zgodnie z procedurą. repair: Nie dotykaj kondensatorów zasilacza sieciowego ani nie otwieraj PSU. Duże kondensatory mogą utrzymywać niebezpieczne napięcie. warning: Zrób zdjęcia i oznacz obszar przed czyszczeniem.','descriptionEn: Inspection may reveal cracks, bulging, leakage, PCB discolouration or burnt connectors. Appearance alone cannot confirm every capacitor failure. symptomsEn: Instability, restarts, no-start symptoms, or visible discolouration and corrosion on the PCB. diagnosisEn: Document the location and compare markings with documentation. Measure capacitance/ESR only after safe isolation and discharge using the approved procedure. repairEn: Never touch mains PSU capacitors or open the PSU. Large capacitors may retain hazardous voltage. warningEn: Photograph and mark the area before cleaning.','',''),
('topic:TOPIC311-007','topic','','Diagnostyka resetów i watchdog w firmware','Firmware watchdog and unexpected-reset diagnostics','description: Reset może wynikać z watchdog, zasilania, temperatury, błędu firmware, sterownika lub sprzętowego fault. Ustal, czy reset poprzedza BSOD, czy następuje bez niego. symptoms: Komputer samoczynnie resetuje się, zawiesza przy starcie lub restartuje po określonym czasie. diagnosis: Porównaj logi Kernel-Power, WHEA i BugCheck. Testuj ustawienia domyślne i stabilną wersję firmware, zgodną z modelem. repair: Nie przerywaj aktualizacji firmware i nie wgrywaj obrazu dla innej rewizji. Przy niestabilnym zasilaniu nie rozpoczynaj flashowania. warning: Zapisz dokładny czas resetu i ostatnie zdarzenia systemowe.','descriptionEn: A reset may result from a watchdog, power, thermal, firmware, driver or hardware fault. Determine whether a BSOD precedes it or the reset occurs without one. symptomsEn: The computer resets unexpectedly, freezes during startup, or restarts after a repeatable interval. diagnosisEn: Compare Kernel-Power, WHEA and BugCheck logs. Test defaults and a stable firmware release for the exact model. repairEn: Never interrupt firmware updates or flash an image for another revision. Do not begin flashing when power is unstable. warningEn: Record the exact reset time and preceding system events.','',''),
('topic:TOPIC311-008','topic','','Diagnostyka błędów pamięci ECC i raportowania RAS','ECC memory and RAS event diagnostics','description: Rozróżnij corrected, uncorrected, patrol scrub, channel, DIMM i zdarzenia kontrolera. Zależnie od platformy raportowanie odbywa się przez BMC, firmware i dzienniki systemowe. symptoms: System raportuje błędy pamięci skorygowane lub nieskorygowane, a serwer może ograniczać wydajność lub zatrzymywać pracę. diagnosis: Zbierz identyfikator DIMM, kanał, rangę i czas zdarzenia. Użyj narzędzi OEM; nie mieszaj modułów poza wspieraną konfiguracją. repair: W środowisku produkcyjnym planuj wymianę z uwzględnieniem redundancji i kopii danych. Nie wyjmuj modułów podczas pracy, jeśli platforma nie wspiera hot-swap. warning: Zapisz model serwera, CPU, BIOS i konfigurację pamięci.','descriptionEn: Distinguish corrected, uncorrected, patrol-scrub, channel, DIMM and controller events. Reporting may use BMC, firmware and OS logs depending on the platform. symptomsEn: The system reports corrected or uncorrected memory errors, and a server may throttle or halt operation. diagnosisEn: Collect DIMM, channel, rank and event-time details. Use OEM tools and do not mix modules outside supported configurations. repairEn: In production, plan replacement with redundancy and data backups in mind. Do not remove modules while powered unless the platform supports hot-swap. warningEn: Record server model, CPU, BIOS and memory configuration.','',''),
('topic:TOPIC311-009','topic','','Diagnostyka dysku sieciowego NAS i RAID degradacji','NAS storage and degraded RAID diagnostics','description: Ustal poziom RAID, liczbę awarii dopuszczalnych, status kontrolera, SMART, błędy linku, zasilanie i temperaturę. Degraded nie jest zgodą na wymuszoną inicjalizację. symptoms: Macierz zgłasza degraded, dysk znika, odbudowa nie startuje lub transfer gwałtownie spada. diagnosis: Zabezpiecz konfigurację i kopię danych. Przed wymianą sprawdź zatwierdzony model dysku i procedurę hot-spare/rebuild producenta NAS. repair: Nie inicjalizuj ponownie macierzy i nie potwierdzaj komunikatu „create array” bez kopii i planu odzyskiwania. warning: Zapisz RAID level, numery zatok i stan każdego dysku.','descriptionEn: Identify RAID level, fault tolerance, controller status, SMART, link errors, power and temperature. A degraded state is not permission to force-initialize. symptomsEn: The array reports degraded status, a drive disappears, rebuild does not start, or throughput drops sharply. diagnosisEn: Protect configuration and data backups. Before replacement, verify an approved drive model and the NAS vendor’s hot-spare/rebuild procedure. repairEn: Do not reinitialize the array or accept a “create array” prompt without a backup and recovery plan. warningEn: Record RAID level, bay numbers and each drive status.','',''),
('topic:TOPIC311-010','topic','','Analiza wydajności CPU: zegary, limity i pobór mocy','CPU performance: clocks, limits and power behaviour','description: Rozróżnij limit termiczny, mocy, prądu, firmware, planu zasilania i ograniczenie platformy. Maksymalny boost nie jest stałą gwarantowaną częstotliwością. symptoms: Procesor działa wolniej niż oczekiwano, obniża zegary lub ma wysoką temperaturę przy niewielkim obciążeniu. diagnosis: Zapisz model CPU, BIOS, chłodzenie, obciążenie i czujniki. Porównuj do specyfikacji konkretnego SKU, nie do innych procesorów. repair: Nie zwiększaj napięcia ani limitów mocy bez znajomości chłodzenia, płyty, gwarancji i ryzyka degradacji. warning: Zapisz wynik bazowy w spoczynku.','descriptionEn: Distinguish thermal, power, current, firmware, power-plan and platform limits. Maximum boost is not a guaranteed sustained frequency. symptomsEn: The CPU performs below expectation, reduces clock speed, or runs hot under modest load. diagnosisEn: Record CPU model, BIOS, cooling, workload and sensors. Compare with the exact SKU specification rather than another processor. repairEn: Do not increase voltage or power limits without understanding cooling, board capability, warranty and degradation risks. warningEn: Record baseline idle measurements.','','');
